    A section with a heading and one PricingCard per plan. Axes: layout (grid, stack), columns, emphasis, billing (off: no toggle; monthly or annual: a toggle with that choice selected, and the prices of that period), density, tone.
    Props (p): id, title, plans, labels, billingLabels, layout, cols, emphasis, billing, tone, density, landmarkLabel. -#}
{%- set v_id = (p.id ?? null) -%}
{%- set v_title = (p.title ?? null) -%}
{%- set v_plans = (p.plans ?? null) -%}
{%- set v_labels = (p.labels ?? null) -%}
{%- set v_billingLabels = (p.billingLabels ?? null) -%}
{%- set v_layout = (p.layout ?? 'grid') -%}
{%- set v_cols = (p.cols ?? '1-3') -%}
{%- set v_emphasis = (p.emphasis ?? 'auto') -%}
{%- set v_billing = (p.billing ?? 'off') -%}
{%- set v_tone = (p.tone ?? 'default') -%}
{%- set v_density = (p.density ?? 'default') -%}
{%- set v_landmarkLabel = (p.landmarkLabel ?? null) -%}
{%- set c_7 -%}
  {%- if ui_t(not (ui_eq(v_billing, 'off'))) %}
    {%- set c_5 -%}
      {%- set c_3 -%}
        {%- set c_1 -%}
          {{ ui_text(ui_get(v_billingLabels, ['monthly'])) }}
        {%- endset -%}
        {{ include('blocks/switcher-item.html.twig', {'p': {'active': ui_eq(v_billing, 'monthly')}, 'children': c_1}, with_context = false) }}
        {%- set c_2 -%}
          {{ ui_text(ui_get(v_billingLabels, ['annual'])) }}
        {%- endset -%}
        {{ include('blocks/switcher-item.html.twig', {'p': {'active': ui_eq(v_billing, 'annual')}, 'children': c_2}, with_context = false) }}
      {%- endset -%}
      {{ include('blocks/switcher.html.twig', {'p': {'label': ui_get(v_billingLabels, ['label'])}, 'children': c_3}, with_context = false) }}
      {%- set c_4 -%}
        {{ ui_text(ui_get(v_billingLabels, ['save'])) }}
      {%- endset -%}
      {{ include('ui/badge/badge.html.twig', {'p': {'Variant': 'default', 'Size': 'default'}, 'children': c_4}, with_context = false) }}
    {%- endset -%}
    {{ include('ui/group/group.html.twig', {'p': {'Gap': '4', 'Align': 'center', 'Justify': 'center', 'Class': 'flex-wrap', 'Attrs': ui_attrs(['data-testid', 'billing'])}, 'children': c_5}, with_context = false) }}
  {%- endif %}
  {%- set c_6 -%}
    {%- for v_plan in ui_l(v_plans) %}
      {{ include('blocks/pricing-card.html.twig', {'p': {'plan': v_plan, 'labels': v_labels, 'emphasis': v_emphasis, 'billing': (ui_t(ui_eq(v_billing, 'annual')) ? 'annual' : 'monthly'), 'density': (ui_t(ui_eq(v_density, 'compact')) ? 'compact' : 'default')}}, with_context = false) }}
    {%- endfor %}
  {%- endset -%}
  {{ include('ui/grid/grid.html.twig', {'p': {'Cols': ui_s((ui_t(ui_eq(v_layout, 'stack')) ? '1' : ui_fit_cols(v_cols, ui_len(v_plans)))), 'Class': 'gap-4', 'Attrs': ui_attrs(['data-testid', 'tiers'])}, 'children': c_6}, with_context = false) }}
{%- endset -%}
{{ include('blocks/section-frame.html.twig', {'p': {'id': v_id, 'title': v_title, 'tone': v_tone, 'density': v_density, 'measure': (ui_t(ui_eq(v_layout, 'stack')) ? 'md' : 'default'), 'landmarkLabel': v_landmarkLabel}, 'children': c_7}, with_context = false) }}
